def find_path(graph, start, goal):
    # Initialize the path and the set of visited nodes
    path = []
    visited = set()

    # Start the search
    def search(node):
        # Mark the node as visited
        visited.add(node)
        path.append(node)
        if node == goal:
            return path
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                result = search(neighbor)
                if result:
                    return result
        # If no path is found, backtrack
        path.pop()
        return None

    # Search from the start node
    return search(start)
