def find_path(graph, start, goal):
    if start == goal:
        return [start]

    visited = set()
    to_visit = [(start, [start])]

    while to_visit:
        (current, path) = to_visit.pop()
        visited.add(current)

        for next_node in graph[current]:
            if next_node not in visited:
                if next_node == goal:
                    return path + [next_node]
                else:
                    to_visit.append((next_node, path + [next_node]))

        # Shorten the order of visited nodes to avoid revisiting
        for node in list(visited):
            if all(node in path for path in to_visit):
                visited.remove(node)

    return None
